        require(dummy == dummy);
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        bool callerIsOwner = (ownerBefore == address(this));

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

